cd /workspace/submission/src/de/rub/nds/tlsattacker/core/quic && python3 - <<'PY'
p='serializer/frame/StreamFrameSerializer.java'
s=open(p).read()
old = """    @Override
    protected byte[] serializeBytes() {
        writeFrameType();
        writeStreamId();
        if (frame.getOffset() != null) {
            writeOffset();
        }
        if (frame.getLength() != null) {
            writeLength();
        }
        writeData();
