    /** True if the frame type carries the offset field. */
    protected boolean hasOffset() {
        return isType(QuicFrameType.STREAM_FRAME_OFF)
                || isType(QuicFrameType.STREAM_FRAME_OFF_FIN)
                || isType(QuicFrameType.STREAM_FRAME_OFF_LEN)
                || isType(QuicFrameType.STREAM_FRAME_OFF_LEN_FIN);
