    /** True if the frame type carries the length field. */
    protected boolean hasLength() {
        return isType(QuicFrameType.STREAM_FRAME_LEN)
                || isType(QuicFrameType.STREAM_FRAME_LEN_FIN)
                || isType(QuicFrameType.STREAM_FRAME_OFF_LEN)
                || isType(QuicFrameType.STREAM_FRAME_OFF_LEN_FIN);
    }

    private boolean isType(QuicFrameType type) {
        return QuicFrameType.getFrameType(frame.getFrameType().getValue()) == type;
    }"""
